//! Required real first-user/native/config producers on both migrated engines.
use axum::{body::{Body,to_bytes},http::{Request,StatusCode}};
use serde_json::{json,Value};use sqlx::{AnyPool,Connection,Column,Row};use tower::ServiceExt;
use std::{path::{Path,PathBuf},collections::BTreeMap,io::Read};use sha2::{Digest,Sha256};
const JWT:&str="owned-password-fixture-secret";const PASSWORD:&str="owned-fixture-password-not-a-real-account";
fn workspace()->PathBuf{PathBuf::from(std::env::var("STARLANE_TOTP_WORKSPACE").expect("required owned TOTP workspace"))}
async fn pool(url:&str,schema:&str)->AnyPool{sqlx::any::install_default_drivers();let engine=crate::db::DatabaseEngine::from_url(url).unwrap();let schema=schema.to_owned();sqlx::any::AnyPoolOptions::new().max_connections(3).after_connect(move|c,_|{let schema=schema.clone();Box::pin(async move{match engine{crate::db::DatabaseEngine::Postgres=>{sqlx::query(&format!("SET search_path TO {schema}")).execute(c).await?;},crate::db::DatabaseEngine::Sqlite=>{sqlx::query("PRAGMA foreign_keys=ON").execute(&mut*c).await?;sqlx::query("PRAGMA busy_timeout=5000").execute(c).await?;}}Ok(())})}).connect(url).await.unwrap()}
fn state(db:AnyPool,root:&Path)->crate::AppState{crate::AppState{db,jwt_secret:JWT.into(),base_url:"http://owned.invalid".into(),search_index:crate::search::SearchIndex::new(root.join("search_index")).unwrap(),oauth_cache:crate::auth::routes::OAuthStateCache::new(),ws_rooms:crate::sync::WsRooms::default()}}

async fn call(s:&crate::AppState,token:Option<&str>,method:&str,uri:&str,body:Value)->(StatusCode,Value){println!("TOTP_STEP {method} {uri}");let mut q=Request::builder().method(method).uri(uri).header("Content-Type","application/json");if let Some(t)=token{q=q.header("Authorization",format!("Bearer {t}"));}let mut req=q.body(Body::from(body.to_string())).unwrap();req.extensions_mut().insert(axum::extract::ConnectInfo("127.0.0.1:43123".parse::<std::net::SocketAddr>().unwrap()));let r=crate::api_routes().with_state(s.clone()).oneshot(req).await.unwrap();let code=r.status();let bytes=to_bytes(r.into_body(),4*1024*1024).await.unwrap();(code,if bytes.is_empty(){Value::Null}else{serde_json::from_slice(&bytes).unwrap_or(json!({"non_json":true}))})}
async fn ok(s:&crate::AppState,token:Option<&str>,method:&str,uri:&str,body:Value)->Value{let(code,v)=call(s,token,method,uri,body).await;assert!(code.is_success(),"actual {method} {uri} status={code}; response suppressed to protect credentials");v}
fn access(v:&Value)->&str{v["access_token"].as_str().unwrap()}fn refresh(v:&Value)->&str{v["refresh_token"].as_str().unwrap()}fn sid(v:&Value)->String{crate::auth::jwt::validate_token(access(v),JWT,crate::auth::jwt::TokenType::Access).unwrap().sid}
async fn snapshot(db:&AnyPool,tables:&[&str])->BTreeMap<String,Vec<Value>>{let mut out=BTreeMap::new();for table in tables{let mut values=Vec::new();for row in sqlx::query(&format!("SELECT * FROM {table}")).fetch_all(db).await.unwrap(){let mut cells=BTreeMap::new();for col in row.columns(){let n=col.name();let v=if let Ok(v)=row.try_get::<Option<String>,_>(n){v.map(|v|json!(["text",v])).unwrap_or(json!(["null"]))}else if let Ok(v)=row.try_get::<Option<i64>,_>(n){v.map(|v|json!(["integer",v.to_string()])).unwrap_or(json!(["null"]))}else if let Ok(v)=row.try_get::<Option<Vec<u8>>,_>(n){v.map(|v|json!(["blob",hex::encode(v)])).unwrap_or(json!(["null"]))}else{panic!("unsupported cell {table}.{n}")};cells.insert(n.to_string(),v);}values.push(serde_json::to_value(cells).unwrap());}values.sort_by_cached_key(Value::to_string);out.insert(table.to_string(),values);}out}
fn login_body(email:&str,password:&str)->Value{json!({"email":email,"password":password,"device_name":"Owned browser","session_kind":"browser","client_platform":"web"})}
fn bytes(root:&Path)->BTreeMap<String,String>{fn walk(root:&Path,p:&Path,out:&mut BTreeMap<String,String>){let m=std::fs::symlink_metadata(p).unwrap();assert!(!m.file_type().is_symlink());if m.is_dir(){for e in std::fs::read_dir(p).unwrap(){walk(root,&e.unwrap().path(),out);}}else{assert!(m.is_file());let mut f=std::fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0u8;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}out.insert(p.strip_prefix(root).unwrap().to_string_lossy().into(),hex::encode(h.finalize()));}}let mut out=BTreeMap::new();for n in["spaces",".storage-journal",".publication-journal",".canonical-rewrite-journal",".move-relocation-journal"]{let p=root.join(n);if p.exists(){walk(root,&p,&mut out);}}out}



const EMAIL:&str="totp-owner@owned.invalid";
const DOMAIN:&[&str]=&["users","sessions","spaces","space_members","documents","document_drafts","storage_journal_receipts","system_config","audit_log"];
const STABLE:&[&str]=&["users","spaces","space_members","documents","document_drafts","storage_journal_receipts","system_config"];
async fn domain(s:&crate::AppState)->BTreeMap<String,Vec<Value>>{snapshot(&s.db,DOMAIN).await}
fn code(secret:&str)->String{totp_rs::TOTP::new(totp_rs::Algorithm::SHA1,6,1,30,totp_rs::Secret::Encoded(secret.into()).to_bytes().unwrap(),None,String::new()).unwrap().generate_current().unwrap()}
fn with_code(c:&str)->Value{let mut b=login_body(EMAIL,PASSWORD);b["totp_code"]=json!(c);b}
async fn setup(s:&crate::AppState,a:&Value)->(String,Vec<String>){let x=ok(s,Some(access(a)),"POST","/auth/2fa/totp/setup",json!({})).await;let uri=reqwest::Url::parse(x["qr_code_url"].as_str().unwrap()).unwrap();let secret=uri.query_pairs().find(|(k,_)|k=="secret").unwrap().1.into_owned();let codes=x["recovery_codes"].as_array().unwrap().iter().map(|x|x.as_str().unwrap().to_owned()).collect::<Vec<_>>();assert_eq!(codes.len(),8);let response=ok(s,Some(access(a)),"POST","/auth/2fa/totp/verify",json!({"code":code(&secret)})).await;assert_eq!(response["totp_enabled"],true);(secret,codes)}
async fn denied_login(s:&crate::AppState,body:Value,status:StatusCode){let b=domain(s).await;let f=bytes(&crate::storage::data_dir());assert_eq!(call(s,None,"POST","/auth/login",body).await.0,status);assert!(b==domain(s).await,"denied TOTP login changed authoritative state");assert_eq!(f,bytes(&crate::storage::data_dir()));}
async fn rollback(s:&crate::AppState,engine:&str,recovery:&str){let before=domain(s).await;let files=bytes(&crate::storage::data_dir());if engine=="sqlite"{sqlx::query("CREATE TRIGGER totp_fail AFTER INSERT ON sessions BEGIN SELECT RAISE(ABORT,'owned TOTP failure'); END").execute(&s.db).await.unwrap();}else{sqlx::query("CREATE FUNCTION totp_fail_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'owned TOTP failure'; END $$").execute(&s.db).await.unwrap();sqlx::query("CREATE TRIGGER totp_fail AFTER INSERT ON sessions FOR EACH ROW EXECUTE FUNCTION totp_fail_fn()").execute(&s.db).await.unwrap();}assert_eq!(call(s,None,"POST","/auth/login",with_code(recovery)).await.0,StatusCode::INTERNAL_SERVER_ERROR);assert!(before==domain(s).await,"session failure consumed actual issued recovery code");assert_eq!(files,bytes(&crate::storage::data_dir()));if engine=="sqlite"{sqlx::query("DROP TRIGGER totp_fail").execute(&s.db).await.unwrap();}else{sqlx::query("DROP TRIGGER totp_fail ON sessions").execute(&s.db).await.unwrap();sqlx::query("DROP FUNCTION totp_fail_fn()").execute(&s.db).await.unwrap();}println!("TOTP_REAL_SESSION_ROLLBACK_PASS");}
async fn racing(s:crate::AppState,c:String,b:std::sync::Arc<tokio::sync::Barrier>)->(StatusCode,Value){let hook:std::pin::Pin<Box<dyn std::future::Future<Output=()>+Send>>=Box::pin(async move{b.wait().await;});crate::auth::routes::TOTP_RECOVERY_PROGRESS.scope(std::cell::RefCell::new(Some(hook)),call(&s,None,"POST","/auth/login",with_code(&c))).await}
async fn activity_wait(s:&crate::AppState,uid:&str,c:&str){let mut held=s.db.begin().await.unwrap();crate::spaces::mutation_guards::lock_audience_for_mutation(&mut held).await.unwrap();sqlx::query("UPDATE users SET is_active=0 WHERE id=$1").bind(uid).execute(&mut*held).await.unwrap();let before=snapshot(&s.db,&["sessions"]).await;let n=std::sync::Arc::new(tokio::sync::Notify::new());let notice=n.clone();let hook:std::pin::Pin<Box<dyn std::future::Future<Output=()>+Send>>=Box::pin(async move{notice.notify_one();});let owned=s.clone();let c=c.to_owned();let task=tokio::spawn(async move{crate::auth::routes::TOTP_RECOVERY_PROGRESS.scope(std::cell::RefCell::new(Some(hook)),call(&owned,None,"POST","/auth/login",with_code(&c))).await});n.notified().await;tokio::time::sleep(std::time::Duration::from_millis(50)).await;assert!(!task.is_finished(),"actual lifecycle fence did not block");held.commit().await.unwrap();assert_eq!(task.await.unwrap().0,StatusCode::UNAUTHORIZED);assert!(before==snapshot(&s.db,&["sessions"]).await);sqlx::query("UPDATE users SET is_active=1 WHERE id=$1").bind(uid).execute(&s.db).await.unwrap();println!("TOTP_REAL_ACTIVITY_WAIT_PASS");}
async fn disable_failure(s:&crate::AppState,engine:&str,a:&Value,c:&str){let before=snapshot(&s.db,&["users"]).await;let files=bytes(&crate::storage::data_dir());if engine=="sqlite"{sqlx::query("CREATE TRIGGER totp_disable_fail BEFORE UPDATE OF totp_enabled ON users WHEN NEW.totp_enabled=0 BEGIN SELECT RAISE(ABORT,'owned TOTP disable failure'); END").execute(&s.db).await.unwrap();}else{sqlx::query("CREATE FUNCTION totp_disable_fail_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.totp_enabled=0 THEN RAISE EXCEPTION 'owned TOTP disable failure'; END IF; RETURN NEW; END $$").execute(&s.db).await.unwrap();sqlx::query("CREATE TRIGGER totp_disable_fail BEFORE UPDATE OF totp_enabled ON users FOR EACH ROW EXECUTE FUNCTION totp_disable_fail_fn()").execute(&s.db).await.unwrap();}assert_eq!(call(s,Some(access(a)),"POST","/auth/2fa/totp/disable",json!({"code":c})).await.0,StatusCode::INTERNAL_SERVER_ERROR);assert!(before==snapshot(&s.db,&["users"]).await,"disable failure consumed recovery code");assert_eq!(files,bytes(&crate::storage::data_dir()));if engine=="sqlite"{sqlx::query("DROP TRIGGER totp_disable_fail").execute(&s.db).await.unwrap();}else{sqlx::query("DROP TRIGGER totp_disable_fail ON users").execute(&s.db).await.unwrap();sqlx::query("DROP FUNCTION totp_disable_fail_fn()").execute(&s.db).await.unwrap();}println!("TOTP_REAL_DISABLE_ROLLBACK_PASS");}
async fn journey(s:&crate::AppState,engine:&str,kind:&str)->Value{
assert!(std::env::var_os("REQUIRE_2FA").is_none(),"owned fixture requires no external REQUIRE_2FA override");
let a=ok(s,None,"POST","/auth/register",json!({"email":EMAIL,"display_name":"TOTP owner","password":PASSWORD,"device_name":"Owned signup"})).await;
let login=ok(s,None,"POST","/auth/login",login_body(EMAIL,PASSWORD)).await;let uid=a["user"]["id"].as_str().unwrap();assert_eq!(login["user"]["id"],uid);
let space:String=sqlx::query_scalar("SELECT id FROM spaces WHERE created_by=$1").bind(uid).fetch_one(&s.db).await.unwrap();
let page=ok(s,Some(access(&login)),"POST",&format!("/spaces/{space}/documents"),json!({"source_id":"totp-page","title":"Exact TOTP page","content":"EXACT_TOTP_PAGE Ω","property_values":[]})).await;
ok(s,Some(access(&login)),"POST",&format!("/spaces/{space}/documents/totp-page/drafts/{}/publish",page["draft_id"].as_str().unwrap()),json!({})).await;
let(secret,recovery)=setup(s,&login).await;
denied_login(s,login_body(EMAIL,PASSWORD),StatusCode::FORBIDDEN).await;
denied_login(s,with_code("invalid-code"),StatusCode::UNAUTHORIZED).await;
let valid=ok(s,None,"POST","/auth/login",with_code(&code(&secret))).await;assert_eq!(valid["user"]["id"],uid);assert_eq!(valid["user"]["totp_enabled"],true);
if kind=="sessionrollback"{rollback(s,engine,&recovery[0]).await;} if kind=="activitywait"{activity_wait(s,uid,&recovery[0]).await;}
let recovered=if kind=="concurrency"{let b=std::sync::Arc::new(tokio::sync::Barrier::new(2));let(sa,sb)=(s.clone(),s.clone());let(ca,cb)=(recovery[0].clone(),recovery[0].clone());let(ba,bb)=(b.clone(),b.clone());let existing=snapshot(&s.db,&["sessions"]).await["sessions"].len();let (a,b)=tokio::join!(tokio::spawn(racing(sa,ca,ba)),tokio::spawn(racing(sb,cb,bb)));let(a,b)=(a.unwrap(),b.unwrap());assert!((a.0==StatusCode::OK&&b.0==StatusCode::UNAUTHORIZED)||(b.0==StatusCode::OK&&a.0==StatusCode::UNAUTHORIZED),"same issued recovery code authenticated twice: {} / {}",a.0,b.0);assert_eq!(snapshot(&s.db,&["sessions"]).await["sessions"].len(),existing+1);println!("TOTP_REAL_ONE_RECOVERY_PASS");if a.0==StatusCode::OK{a.1}else{b.1}}else{ok(s,None,"POST","/auth/login",with_code(&recovery[0])).await};assert_eq!(recovered["user"]["id"],uid);
denied_login(s,with_code(&recovery[0]),StatusCode::UNAUTHORIZED).await;
let stored:String=sqlx::query_scalar("SELECT recovery_codes FROM users WHERE id=$1").bind(uid).fetch_one(&s.db).await.unwrap();assert_eq!(serde_json::from_str::<Vec<String>>(&stored).unwrap().len(),7);
if kind=="policy"{ok(s,Some(access(&recovered)),"POST","/admin/config",json!({"key":"require_2fa","value":"true"})).await;let before=snapshot(&s.db,&["users"]).await;assert_eq!(call(s,Some(access(&recovered)),"POST","/auth/2fa/totp/disable",json!({"code":recovery[1]})).await.0,StatusCode::FORBIDDEN);assert!(before==snapshot(&s.db,&["users"]).await);ok(s,Some(access(&recovered)),"POST","/admin/config",json!({"key":"require_2fa","value":"false"})).await;println!("TOTP_REAL_CONFIG_POLICY_PASS");}
if kind=="disablerollback"{disable_failure(s,engine,&recovered,&recovery[1]).await;}
let before=snapshot(&s.db,&["users"]).await;assert_eq!(call(s,Some(access(&recovered)),"POST","/auth/2fa/totp/disable",json!({"code":"invalid-code"})).await.0,StatusCode::UNAUTHORIZED);assert!(before==snapshot(&s.db,&["users"]).await);
let disabled=ok(s,Some(access(&recovered)),"POST","/auth/2fa/totp/disable",json!({"code":recovery[1]})).await;assert_eq!(disabled["totp_enabled"],false);
let u:(i32,Option<String>,Option<String>)=sqlx::query_as("SELECT totp_enabled,totp_secret,recovery_codes FROM users WHERE id=$1").bind(uid).fetch_one(&s.db).await.unwrap();assert_eq!(u,(0,None,None));
let disabled_login=ok(s,None,"POST","/auth/login",login_body(EMAIL,PASSWORD)).await;
let(new_secret,_)=setup(s,&disabled_login).await;
let stable=snapshot(&s.db,STABLE).await;let files=bytes(&crate::storage::data_dir());assert!(!files.is_empty());println!("TOTP_ACTUAL_PRODUCER_PASS {kind}");json!({"login":disabled_login,"secret":new_secret,"space":space,"stable":stable,"files":files})}
async fn run(engine:&str,kind:&str){let root=crate::storage::data_dir();assert!(root.starts_with(workspace()));let url=if engine=="postgres"{std::env::var("STARLANE_TOTP_PG_URL").expect("required owned TOTP PG URL")}else{format!("sqlite://{}?mode=rwc",root.join("starlane-notes.db").display())};std::fs::create_dir_all(&root).unwrap();let schema=if engine=="postgres"{sqlx::any::install_default_drivers();let name=format!("totp_{}",uuid::Uuid::new_v4().simple());let mut c=sqlx::AnyConnection::connect(&url).await.unwrap();sqlx::query(&format!("CREATE SCHEMA {name}")).execute(&mut c).await.unwrap();c.close().await.unwrap();name}else{String::new()};let db=pool(&url,&schema).await;crate::db::migrate_selected(&db,crate::db::DatabaseEngine::from_url(&url).unwrap()).await.unwrap();let s=state(db,&root);let e=journey(&s,engine,kind).await;std::fs::write(workspace().join("expected.json"),e.to_string()).unwrap();s.db.close().await;drop(s);let child=std::process::Command::new(std::env::current_exe().unwrap()).args(["postgres_totp_fixture::fresh_totp_child","--ignored","--exact","--nocapture"]).env("STARLANE_TOTP_CHILD_URL",url).env("STARLANE_TOTP_SCHEMA",schema).output().unwrap();assert!(child.status.success(),"{}\n{}",String::from_utf8_lossy(&child.stdout),String::from_utf8_lossy(&child.stderr));println!("TOTP_FRESH_CHILD {}",String::from_utf8_lossy(&child.stdout));}
macro_rules! case{($name:ident,$engine:literal,$kind:literal)=>{#[tokio::test]#[ignore="required owned TOTP orchestration"]async fn $name(){run($engine,$kind).await;}};}
case!(required_postgres_flow,"postgres","flow");case!(required_sqlite_flow,"sqlite","flow");
case!(required_postgres_sessionrollback,"postgres","sessionrollback");case!(required_sqlite_sessionrollback,"sqlite","sessionrollback");
case!(required_postgres_concurrency,"postgres","concurrency");case!(required_sqlite_concurrency,"sqlite","concurrency");
case!(required_postgres_policy,"postgres","policy");case!(required_sqlite_policy,"sqlite","policy");
case!(required_postgres_activitywait,"postgres","activitywait");case!(required_sqlite_activitywait,"sqlite","activitywait");
case!(required_postgres_disablerollback,"postgres","disablerollback");case!(required_sqlite_disablerollback,"sqlite","disablerollback");
#[tokio::test]#[ignore="only genuine TOTP parent launches"]async fn fresh_totp_child(){let url=std::env::var("STARLANE_TOTP_CHILD_URL").expect("required TOTP child URL");let schema=std::env::var("STARLANE_TOTP_SCHEMA").expect("required parent schema");let root=crate::storage::data_dir();assert!(root.starts_with(workspace()));let e:Value=serde_json::from_slice(&std::fs::read(workspace().join("expected.json")).unwrap()).unwrap();let s=state(pool(&url,&schema).await,&root);assert_eq!(serde_json::to_value(snapshot(&s.db,STABLE).await).unwrap(),e["stable"]);crate::storage::restoration::bootstrap_gate(&root).unwrap();crate::storage::restoration::activate_in(&root,&s.db).await.unwrap();crate::storage::relocation::recover(&s.db).await.unwrap();crate::storage::journal::recover(&s.db).await.unwrap();crate::storage::canonical_rewrite::recover(&s.db).await.unwrap();crate::storage::publication::recover(&s.db).await.unwrap();crate::storage::attachment_upload::recover_in(&root,&s.db).await.unwrap();assert_eq!(serde_json::to_value(snapshot(&s.db,STABLE).await).unwrap(),e["stable"]);let me=ok(&s,Some(access(&e["login"])),"GET","/auth/me",Value::Null).await;let a=ok(&s,None,"POST","/auth/login",with_code(&code(e["secret"].as_str().unwrap()))).await;assert_eq!(a["user"]["id"],me["id"]);assert_eq!(a["user"]["totp_enabled"],true);let content=ok(&s,Some(access(&a)),"GET",&format!("/spaces/{}/documents/totp-page/content",e["space"].as_str().unwrap()),Value::Null).await;assert!(content["content"].as_str().unwrap().contains("EXACT_TOTP_PAGE Ω"));assert_eq!(serde_json::to_value(bytes(&root)).unwrap(),e["files"]);s.db.close().await;drop(s);println!("TOTP_ACTUAL_FRESH_RESTART_PASS");}
